import{_ as s,c as r,o as n,ag as i}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Business","description":"","frontmatter":{"title":"Business"},"headers":[],"relativePath":"general/business.md","filePath":"general/business.md","lastUpdated":null}'),a={name:"general/business.md"};function t(o,e,u,l,c,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="business" tabindex="-1">Business <a class="header-anchor" href="#business" aria-label="Permalink to &quot;Business&quot;">​</a></h1><h2 id="the-business-chat-page" tabindex="-1">The Business Chat Page <a class="header-anchor" href="#the-business-chat-page" aria-label="Permalink to &quot;The Business Chat Page&quot;">​</a></h2><p>Welcome to the Civilian-Military Business Chat Archive. This section is a comprehensive resource for veterans and civilians looking to explore business insights, connect with others, and access valuable resources. Navigate through our curated discussions and resources to enhance your business acumen and networks.</p><p>A sanctuary for military personnel venturing into business, addressing the distinct divide many feel in traditional workplaces, and fostering a community bound by collective experience, intelligence, and ambition.</p><p>This chat prioritizes mentorship, financial strategies, and opportunities to redefine career narratives and empower members to carve out prosperous, harmonized futures in both domains.</p><h3 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h3><h3 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h3><ul><li><p><strong><a href="https://signal.group/#CjQKIBiE-V-2KP7nvkWKUAU3_yoERGzs3yWdxUq2Uo5PzmLBEhAkNLZ8yO6hHieG6favRCLC" target="_blank" rel="noreferrer">Business Chat - Signal</a></strong> - Signal Community Chat focused on business ventures and resources especially for service members and veterans.</p></li><li><p><strong>Overview</strong> - Explore detailed connections and collaborations formed within our community.</p></li><li><p><strong><a href="https://forum.irregularchat.com/t/business-chat-introductions/100" target="_blank" rel="noreferrer">Business Connections and Intros</a></strong> - Participate in ongoing discussions about business opportunities and partnerships. (Login Required)</p></li></ul><h3 id="business-resources" tabindex="-1">Business Resources <a class="header-anchor" href="#business-resources" aria-label="Permalink to &quot;Business Resources&quot;">​</a></h3><ul><li><strong><a href="/general/business.html">Resources Home</a></strong> - Access a wide range of tools, guides, and articles designed to support your business ventures.</li></ul><h3 id="programs-highlight" tabindex="-1">Programs Highlight <a class="header-anchor" href="#programs-highlight" aria-label="Permalink to &quot;Programs Highlight&quot;">​</a></h3><p>Highlighting specific programs that are tailored to veterans and their unique business needs:</p><ul><li><p><strong>Pentagon Federal Credit Union Foundation’s VEIP Program</strong>: Offers financial assistance and mentorship to veteran entrepreneurs.</p></li><li><p><strong>Bunker Labs CEO Circle</strong>: A networking group providing support and guidance from established veteran CEOs.</p></li><li><p><strong>NYU Tandon’s Apex Program</strong>: Focuses on advanced technological support and business incubation for veteran-led startups.</p></li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><p>Explore more resources to further support your business endeavors:</p><ul><li><p><strong><a href="https://vets.sba.gov/" target="_blank" rel="noreferrer">Veteran Entrepreneurship Training Series</a></strong> - A series of free courses aimed at helping veterans start and run successful businesses.</p></li><li><p><strong><a href="https://www.vetfran.org/" target="_blank" rel="noreferrer">VetFran Business Grant Program</a></strong> - Grants and franchise opportunities for veterans interested in starting their own business.</p></li></ul><h3 id="how-to-contribute" tabindex="-1">How to Contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to Contribute&quot;">​</a></h3><p>Interested in contributing to the Civ-Mil Business Chat? Here’s how you can get involved:</p><ul><li><p><strong>Start a Discussion</strong>: Share your experiences or ask for advice on our <a href="https://github.com/orgs/irregularchat/discussions" target="_blank" rel="noreferrer">GitHub Discussion page</a>.</p></li><li><p><strong>Submit a Resource</strong>: If you have resources or tools beneficial to our community, please submit them for inclusion in our resource directory.</p></li></ul><p>We encourage all community members to dive into these resources and discussions to build stronger business connections and gain valuable insights into entrepreneurship and business management.</p><p>[Required]</p>',21)])])}const g=s(a,[["render",t]]);export{p as __pageData,g as default};
